import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t,P as n,q as a}from"./D3cAVrQp.js";var o=t("<h1>Global Health Preparedness, Outbreak Response, and Biosecurity Framework v2.2.2</h1> <h2>Community Health Capacity, Lawful Emergency Response, Biological-Risk Prevention, and Equitable Countermeasure Access</h2> <p><strong>Document type:</strong> Tier 2 Foundational Application Layer — Core Governance Document<br> <strong>Status:</strong> Constitutional successor draft for expert, community, public-health, labour, disability, Indigenous, and legal review<br> <strong>Version:</strong> 2.2.2<br> <strong>Date:</strong> August 2026<br> <strong>Successor to:</strong> Global Health & Pandemic Security Framework v2.1<br> <strong>Conformance patch to:</strong> Global Health Preparedness, Outbreak Response, and Biosecurity Framework v2.2.1</p> <h3>Controlling interfaces</h3> <ul><li>Treaty for Our Only Home v1.3;</li> <li>Emergency, Catastrophic-Risk, and Continuity Interface Specification v0.1;</li> <li>Emergency and Catastrophic-Risk Cluster Record Profile v0.1 (<code>ECRC/0.1</code>);</li> <li>Emergency Record Inheritance Clause v0.1 (<code>ECRC-RIC/0.1</code>);</li> <li>Emergency Cross-Domain Event Envelope v0.1 (<code>CDEE/0.1</code>);</li> <li>Global Health–Aethelred Biological Incident Coordination Addendum v0.1 (<code>GH-AE-BICA/0.1</code>);</li> <li>Planetary Immune System v2.2.2;</li> <li>Justice Systems Framework v1.4;</li> <li>Aurora Accord v1.3;</li> <li>Technology Governance Framework v3.6;</li> <li>Synoptic Protocol v4.2;</li> <li>Indigenous Sovereignty and Planetary Healing Framework v1.1;</li> <li>Integrated Meta-Governance Framework v1.5;</li> <li>Genesis Protocol v0.9;</li> <li>Work in Liberation Framework v2.0.</li></ul> <h3>Version history</h3> <ul><li><strong>Editorial edition (2026-08-02).</strong> No substantive change. Added this version history, which the document previously lacked; entries below are reconstructed from the framework’s own executive summary and Appendix L compatibility note, and earlier editions remain to be recorded. Normalised the controlling-interfaces block to a section heading matching the rest of the cluster. Pins and digests are unchanged: they are load-bearing here, since the fail-closed rules depend on exact version identity.</li> <li><strong>2.2.2 (August 2026):</strong> Conformance patch to v2.2.1. Adopts the Emergency Record Inheritance Clause and conforms to the Emergency and Catastrophic-Risk Cluster Record Profile to the extent shown in the complete ECRC-01–ECRC-33 crosswalk at Appendix K, with unmapped records imported directly when triggered and recorded gaps blocking the affected consequential action. Pins CDEE/0.1 and the Global Health–Aethelred Biological Incident Coordination Addendum with digests at Appendix L. Per that appendix’s compatibility test, the only changes are version and reference updates and adoption and conformance text; no health, biosafety, genetic, facility, licensing, public-health, emergency-power, rights, evidence, or remedy semantics changed.</li> <li><strong>2.2 (August 2026):</strong> Constitutional successor to the Global Health & Pandemic Security Framework v2.1. Preserved the predecessor’s strongest contribution — an analog immune system built from trusted local health capacity, paper records, radio, rapid tests, offline logistics, and community knowledge that remains functional when digital infrastructure fails — while separating community health capacity, lawful emergency response, biological-risk prevention, and equitable countermeasure access into distinct functions under competent authority.</li> <li><strong>Earlier editions:</strong> not yet recorded in this document.</li></ul> <hr> <h2>Executive constitutional summary</h2> <p>This framework supports communities and competent public institutions in preventing biological harm, detecting outbreaks, coordinating requested assistance, protecting health workers, allocating scarce countermeasures, and learning after emergencies. It preserves the strongest contribution of the previous framework: an <strong>analog immune system</strong> built from trusted local health capacity, paper records, radio, rapid tests, offline logistics, and community knowledge that remains functional when digital infrastructure fails.</p> <p>It does <strong>not</strong> create a global health sovereign. It does not declare emergencies, supersede states or Indigenous nations, command health systems, impose quarantine, require vaccination, license laboratories, close industries, seize assets, levy taxes, adjudicate liability, or transfer World Health Organization functions. Each consequential act requires an independently valid legal basis and an <strong>Emergency Authority Provenance Record</strong>.</p> <blockquote><p><strong>Speed must come from preparedness, local capacity, pre-authorized cooperation, interoperability, and bounded emergency law—not from treating sovereignty, bodily integrity, due process, or community authority as obstacles.</strong></p></blockquote> <p>The framework separates seven functions that v2.1 partially combined:</p> <ol><li>biological-risk observation and state estimation;</li> <li>lawful emergency declaration;</li> <li>logistics and requested assistance;</li> <li>countermeasure allocation;</li> <li>health, environmental, laboratory, and industrial regulation;</li> <li>adjudication and remedy;</li> <li>after-action learning and ordinary-capacity reform.</li></ol> <p>No body controls the full chain.</p> <hr> <h1>1. Purpose, scope, and non-authority</h1> <h2>1.1 Purpose</h2> <p>The framework provides interoperable constitutional, operational, and ethical interfaces for:</p> <ul><li>community health preparedness;</li> <li>outbreak detection and verification;</li> <li>public-health assistance;</li> <li>clinical and non-clinical response;</li> <li>biological-risk prevention;</li> <li>antimicrobial-resistance coordination;</li> <li>equitable access to diagnostics, vaccines, therapeutics, protective equipment, and essential supplies;</li> <li>cross-border health cooperation;</li> <li>continuity of care during emergencies;</li> <li>restoration after wrongful or excessive action.</li></ul> <h2>1.2 Scope</h2> <p>The framework applies to population-health risks arising from:</p> <ul><li>natural pathogen emergence;</li> <li>ecologically or industrially amplified spillover risk;</li> <li>occupational and supply-chain exposure;</li> <li>laboratory accident or containment failure;</li> <li>unsafe biotechnology use or field release;</li> <li>antimicrobial resistance;</li> <li>deliberate biological release;</li> <li>health-system collapse or interruption;</li> <li>unknown or contested origin.</li></ul> <p>Different origins create different evidence requirements, regulatory duties, liabilities, and remedies. The framework does not presume that every outbreak is an industrial accident, laboratory event, deliberate attack, or natural occurrence.</p> <h2>1.3 Non-authority clause</h2> <p>This document is a coordination and design specification. It does not itself:</p> <ul><li>create public-health jurisdiction;</li> <li>declare a public-health emergency;</li> <li>authorize surveillance, isolation, quarantine, vaccination, medical treatment, search, seizure, detention, or use of force;</li> <li>establish criminal or civil liability;</li> <li>designate land or Indigenous territory as a restricted zone;</li> <li>create taxes, compulsory bonds, patent powers, procurement obligations, or market exclusions;</li> <li>transfer authority from the WHO, a state, a local authority, a professional regulator, or an Indigenous nation;</li> <li>authorize a GGF body to override domestic, Indigenous, Treaty, or international law;</li> <li>make participation in a GGF programme a condition of essential care, AUBI Layer 1, justice, or humanitarian assistance.</li></ul> <blockquote><p><strong>No valid authority record, no consequential public-health action.</strong></p></blockquote> <hr> <h1>2. Governing principles</h1> <ol><li><strong>Health with rights:</strong> Public health and individual rights are mutually constitutive. Effective response requires trust, legality, accessibility, and remedy.</li> <li><strong>Prevention before emergency:</strong> Ordinary ecological, occupational, agricultural, laboratory, housing, and health-system regulation should reduce risk before crisis powers are considered.</li> <li><strong>Analog capacity first:</strong> Local people, offline tools, paper systems, radio, clinical judgment, and trusted messengers are primary resilience assets; digital tools are optional amplifiers.</li> <li><strong>Subsidiarity with assistance:</strong> Action remains at the lowest competent level, while higher levels provide requested capability, interoperability, finance, and surge support.</li> <li><strong>No competence-to-authority conversion:</strong> Better performance, expertise, funding, or public trust does not transfer jurisdiction without a valid legal act.</li> <li><strong>Plural observation:</strong> No single model, laboratory, dashboard, government, company, or knowledge system determines the state of an outbreak alone.</li> <li><strong>Proportionality and least restrictive means:</strong> Measures must be suitable, necessary, time-bounded, reviewable, and no broader than required.</li> <li><strong>Equity without categorical disposability:</strong> Vulnerability guides support; it does not reduce a person’s claim to care, liberty, explanation, appeal, or dignity.</li> <li><strong>Indigenous authority and protected non-transfer:</strong> Indigenous peoples determine their own health interfaces, knowledge sharing, territorial access, genetic-data use, and participation.</li> <li><strong>Worker safety and professional integrity:</strong> Health, laboratory, logistics, sanitation, care, and community workers retain labour rights, safety protections, and lawful refusal.</li> <li><strong>Open science with bounded disclosure:</strong> Publicly funded knowledge should be broadly available where safe and lawful, while personal data, protected knowledge, security-sensitive methods, and dual-use details receive appropriate protection.</li> <li><strong>Failure is informative:</strong> False alarms, non-scaling, disputed evidence, unsuccessful pilots, and institutional closure are legitimate outcomes when documented honestly.</li></ol> <hr> <h1>3. Biological-risk and countermeasure interface</h1> <p>This section is shared conceptually with the Aethelred Accord v1.2.2 and other biological-risk frameworks.</p> <h2>3.1 Event-origin classes</h2> <p>Every material biological event should record one or more provisional origin classes:</p> <ul><li><strong>N:</strong> natural emergence;</li> <li><strong>E:</strong> ecological disturbance or land-use amplification;</li> <li><strong>I:</strong> industrial or occupational amplification;</li> <li><strong>L:</strong> laboratory incident or containment failure;</li> <li><strong>B:</strong> biotechnology design, use, or release;</li> <li><strong>D:</strong> suspected deliberate release;</li> <li><strong>U:</strong> unknown, mixed, or contested origin.</li></ul> <p>Origin classification remains provisional until evidence supports a finding by a competent institution. It must not be used as a substitute for proof of fault.</p> <h2>3.2 Event-status classes</h2> <p>The framework distinguishes:</p> <ol><li>signal;</li> <li>anomaly under assessment;</li> <li>suspected cluster;</li> <li>verified event;</li> <li>outbreak;</li> <li>cross-border health event;</li> <li>declared emergency under valid law;</li> <li>persistent health condition requiring ordinary governance;</li> <li>resolved event under surveillance;</li> <li>disputed or unresolved event.</li></ol> <p>A move between classes requires a recorded basis. A technical classification alone does not activate coercive power.</p> <h2>3.3 Countermeasure classes</h2> <p>Countermeasures include:</p> <ul><li>information and voluntary guidance;</li> <li>diagnostic capacity;</li> <li>clinical care;</li> <li>vaccination and prophylaxis;</li> <li>therapeutics;</li> <li>infection-prevention equipment;</li> <li>ventilation and environmental measures;</li> <li>paid leave and income continuity;</li> <li>housing and isolation support;</li> <li>travel and gathering measures;</li> <li>animal-health or agricultural measures;</li> <li>laboratory containment;</li> <li>environmental containment;</li> <li>supply-chain stabilization.</li></ul> <p>Each class has different authority, evidence, equity, liability, and review requirements.</p> <h2>3.4 Shared records</h2> <p>At minimum, cross-framework biological-risk work uses:</p> <ul><li>Biological-Risk Profile;</li> <li>Observation and Sample Provenance Record;</li> <li>Incident-Origin and Confidence Record;</li> <li>Laboratory or Field-Release Handoff Record;</li> <li>Health-Data Authority and Access Record;</li> <li>Dual-Use Information Review Record;</li> <li>Countermeasure Evidence and Authorization Record;</li> <li>Countermeasure Allocation and Equity Record;</li> <li>Health Worker and Responder Safety Record;</li> <li>Emergency Authority Provenance Record;</li> <li>Termination and Restoration Record.</li></ul> <hr> <h1>4. Separation of functions</h1> <p>The following functions must be institutionally distinguishable even when performed by cooperating entities.</p> <table><thead><tr><th>Function</th><th>Permitted role</th><th>Prohibited combination</th></tr></thead><tbody><tr><td>Observation and assessment</td><td>collect signals, test hypotheses, estimate risk</td><td>cannot declare, command, sanction, or determine liability</td></tr><tr><td>Declaration</td><td>make a legally defined emergency declaration</td><td>cannot be self-triggered by the observing institution unless law expressly assigns both roles with safeguards</td></tr><tr><td>Logistics coordination</td><td>match requests, personnel, supplies, transport, and facilities</td><td>cannot impose measures on a host jurisdiction</td></tr><tr><td>Countermeasure allocation</td><td>administer a lawful allocation rule and document scarcity decisions</td><td>cannot create its own funding or deprivation authority</td></tr><tr><td>Regulation</td><td>apply valid health, laboratory, occupational, environmental, or product law</td><td>cannot adjudicate its own contested enforcement action</td></tr><tr><td>Adjudication</td><td>determine rights, evidence, liability, and remedy</td><td>cannot investigate, deploy, or execute its own orders by default</td></tr><tr><td>Enforcement</td><td>carry out a valid order under an identified command and legal basis</td><td>cannot determine guilt or enlarge the order</td></tr><tr><td>Learning</td><td>evaluate performance, failure, and institutional design</td><td>cannot retroactively justify an unauthorized action</td></tr></tbody></table> <p>No coordinating secretariat receives residual authority over unassigned functions.</p> <hr> <h1>5. Federated health-threat observation</h1> <h2>5.1 Health Threat Assessment Network</h2> <p>A <strong>Health Threat Assessment Network</strong> may connect national public-health institutes, regional bodies, the WHO, Indigenous health authorities, universities, laboratories, veterinary and environmental services, community networks, and other competent observers.</p> <p>The network may:</p> <ul><li>receive and compare signals;</li> <li>support verification;</li> <li>maintain methods and interoperability;</li> <li>publish bounded state estimates;</li> <li>record dissent and uncertainty;</li> <li>identify observation gaps;</li> <li>request independent replication;</li> <li>support horizon scanning and exercises.</li></ul> <p>It may not declare an emergency or activate coercive measures.</p> <h2>5.2 Observation independence</h2> <p>For high-consequence events, the state estimate should identify:</p> <ul><li>which observations are independent;</li> <li>shared data, models, funding, laboratories, or supply chains;</li> <li>institutional incentives;</li> <li>missing populations or geographies;</li> <li>uncertainty introduced by censorship, conflict, infrastructure failure, or sample bias;</li> <li>protected knowledge that was not transferred;</li> <li>disagreements among scientific, clinical, community, veterinary, ecological, and Indigenous sources.</li></ul> <p>“Multiple sources” must not be reported as independent when they derive from one upstream dataset or model.</p> <h2>5.3 Public estimates</h2> <p>Public estimates should distinguish:</p> <ul><li>what is observed;</li> <li>what is inferred;</li> <li>what remains unknown;</li> <li>plausible alternative explanations;</li> <li>confidence and time horizon;</li> <li>expected consequences of action and inaction;</li> <li>the authority, if any, responsible for the next decision.</li></ul> <hr> <h1>6. Emergency declaration and activation</h1> <h2>6.1 Declaration</h2> <p>A public-health emergency may be declared only by an institution empowered under applicable law, such as:</p> <ul><li>a competent local, Indigenous, national, regional, Treaty, or international authority;</li> <li>the WHO under its own governing instruments, where applicable;</li> <li>another institution expressly authorized by a ratified health instrument.</li></ul> <p>The framework does not create an alternative PHEIC declaration power.</p> <h2>6.2 Declaration content</h2> <p>A declaration should specify:</p> <ul><li>legal source;</li> <li>territory and population;</li> <li>event and evidence;</li> <li>rights potentially affected;</li> <li>permitted powers;</li> <li>excluded powers;</li> <li>responsible institutions;</li> <li>initial duration;</li> <li>review route;</li> <li>public communication duty;</li> <li>termination criteria.</li></ul> <h2>6.3 Activation is power-specific</h2> <p>A declaration does not automatically activate:</p> <ul><li>foreign deployment;</li> <li>mandatory isolation or quarantine;</li> <li>vaccination requirements;</li> <li>data access;</li> <li>procurement powers;</li> <li>property requisition;</li> <li>industrial closure;</li> <li>border measures;</li> <li>military or police support;</li> <li>PIS coordination.</li></ul> <p>Each requires a separate activation schedule with its own legal basis.</p> <h2>6.4 Time architecture</h2> <p>The Emergency Interface’s default architecture applies:</p> <ul><li>narrowly provisional measures: no more than 72 hours without the required review;</li> <li>continued extraordinary measures: renewal no longer than 30 days at a time;</li> <li>extraordinary operation beyond 90 cumulative days: heightened review and a transition plan to ordinary law.</li></ul> <p>Persistent conditions must not be governed indefinitely through repeated emergency renewal.</p> <hr> <h1>7. Global Health Coordination Secretariat</h1> <p>The former Global Health Security Council is reconstituted as a <strong>Global Health Coordination Secretariat (GHCS)</strong>.</p> <h2>7.1 Permitted functions</h2> <p>The GHCS may:</p> <ul><li>maintain voluntary coordination agreements;</li> <li>receive requests for assistance;</li> <li>match needs with available personnel and supplies;</li> <li>maintain logistics and interoperability directories;</li> <li>facilitate regional stockpile cooperation;</li> <li>support joint exercises;</li> <li>maintain translation and accessibility capacity;</li> <li>document resource gaps;</li> <li>convene technical and community consultations;</li> <li>publish non-binding operational recommendations;</li> <li>support after-action reviews.</li></ul> <h2>7.2 Prohibited functions</h2> <p>The GHCS may not:</p> <ul><li>declare a health emergency;</li> <li>impose quarantine, vaccination, surveillance, or border measures;</li> <li>command domestic health systems;</li> <li>allocate supplies without an adopted allocation mandate;</li> <li>certify or decertify industries;</li> <li>designate land-use zones;</li> <li>impose fines, bonds, asset freezes, or market exclusions;</li> <li>transfer WHO or state functions to itself;</li> <li>deploy personnel without a valid request, agreement, or pre-authorization;</li> <li>renew its own emergency mandate.</li></ul> <h2>7.3 Governance</h2> <p>Its charter should provide:</p> <ul><li>regional and community participation without claiming universal representation;</li> <li>affected-nation Indigenous interfaces rather than a universal proxy;</li> <li>professional, labour, disability, patient, public-health, veterinary, and environmental expertise;</li> <li>financial and institutional conflict-of-interest rules;</li> <li>transparent agendas and reasons, subject to health, privacy, security, and protected-knowledge limits;</li> <li>independent audit and complaint routes;</li> <li>first-seating and non-activation rules under Genesis v0.9.</li></ul> <hr> <h1>8. Community Health Readiness Networks</h1> <p>The former militarized label is retired; local capacity is organized as <strong>Community Health Readiness Networks</strong>.</p> <h2>8.1 Functions</h2> <p>A network may support:</p> <ul><li>health education;</li> <li>symptom and event reporting;</li> <li>translation and cultural liaison;</li> <li>voluntary caregiving;</li> <li>navigation to clinical services;</li> <li>distribution of supplies;</li> <li>community preparedness;</li> <li>accessibility checks;</li> <li>welfare and family support;</li> <li>radio and offline communication;</li> <li>community-led evaluation.</li></ul> <p>Clinical diagnosis, prescribing, vaccination, specimen collection, treatment, and compulsory measures remain subject to professional and public-health law.</p> <h2>8.2 Employment and labour</h2> <p>Community participation must not be used to replace paid health work. Where work is regular, directed, hazardous, or essential, ordinary compensation, insurance, training, supervision, rest, protective equipment, and collective representation are required.</p> <p>Hearts or other recognition systems may not substitute for wages or create eligibility for essential services.</p> <h2>8.3 Safety and non-retaliation</h2> <p>Workers and volunteers retain rights to:</p> <ul><li>decline unsafe tasks;</li> <li>report shortages or misconduct;</li> <li>receive protective equipment and training;</li> <li>obtain exposure follow-up and compensation;</li> <li>withdraw from roles without loss of AUBI Layer 1 or essential care;</li> <li>protect confidential patient and community information;</li> <li>refuse compulsory extraction of Indigenous or community knowledge.</li></ul> <h2>8.4 Local authority</h2> <p>Networks are chartered by competent local, Indigenous, health, civil-society, or public institutions. A GGF framework cannot create them universally or assign them territorial authority.</p> <hr> <h1>9. Health Emergency Assistance Corps</h1> <p>A <strong>Health Emergency Assistance Corps (HEAC)</strong> may provide deployable health, laboratory, logistics, engineering, translation, accessibility, and psychosocial assistance.</p> <h2>9.1 Separate charter</h2> <p>The HEAC requires a legally valid charter defining:</p> <ul><li>legal personality;</li> <li>scope of practice;</li> <li>recruitment and credentialing;</li> <li>deployment request and acceptance;</li> <li>host authority;</li> <li>operational command;</li> <li>facility and clinical standards;</li> <li>procurement;</li> <li>records and data;</li> <li>security support;</li> <li>immunity and liability;</li> <li>worker rights;</li> <li>complaints and remedies;</li> <li>termination and withdrawal;</li> <li>after-action review.</li></ul> <h2>9.2 Deployment bases</h2> <p>Deployment may occur through:</p> <ul><li>a request from a competent host authority;</li> <li>a standing mutual-assistance agreement;</li> <li>valid Treaty or international authorization;</li> <li>narrow immediate rescue where the Emergency Interface permits it.</li></ul> <p>A declaration elsewhere does not authorize entry into a territory.</p> <h2>9.3 Immunity and accountability</h2> <p>No framework may self-grant diplomatic immunity. Any immunity must be conferred by valid law or agreement, remain functionally necessary and proportionate, and preserve pathways for claims, professional discipline, serious misconduct investigation, and compensation.</p> <h2>9.4 Command</h2> <p>Mission command is limited to the accepted assistance mandate. The HEAC does not command domestic hospitals, public-health agencies, police, militaries, or community networks unless a valid instrument explicitly provides otherwise.</p> <hr> <h1>10. The analog immune system</h1> <h2>10.1 Continuity objective</h2> <p>Every participating jurisdiction should be capable of essential outbreak detection and response during loss of internet, cloud services, electricity, digital identity, payment systems, or centralized supply chains.</p> <h2>10.2 Core offline capacity</h2> <p>The minimum locally adapted set may include:</p> <ul><li>picture- and language-accessible symptom guidance;</li> <li>paper case definitions and reporting forms;</li> <li>radio and messenger protocols;</li> <li>locally maintainable rapid diagnostics where appropriate;</li> <li>specimen-storage and transport procedures;</li> <li>paper contact and exposure records;</li> <li>pre-positioned protective equipment;</li> <li>water, sanitation, ventilation, and waste protocols;</li> <li>local isolation support that preserves dignity and family contact;</li> <li>accessible public warnings;</li> <li>continuity plans for medicines, food, income, and caregiving.</li></ul> <h2>10.3 Digital enhancement</h2> <p>Digital tools may support but not constitutionally replace:</p> <ul><li>clinical judgment;</li> <li>accessible non-digital participation;</li> <li>independent verification;</li> <li>human review;</li> <li>lawful authorization;</li> <li>local fallback capacity.</li></ul> <p>No person should lose care or legal protection because they lack a device, biometric credential, digital identity, or data connection.</p> <hr> <h1>11. Detection, verification, and reporting</h1> <h2>11.1 Reporting thresholds</h2> <p>Reporting protocols should distinguish:</p> <ul><li>individual clinical suspicion;</li> <li>unusual cluster;</li> <li>laboratory confirmation;</li> <li>epidemiological linkage;</li> <li>community or ecological signal;</li> <li>occupational signal;</li> <li>animal-health signal;</li> <li>verified outbreak criteria.</li></ul> <h2>11.2 No automatic power</h2> <p>A signal or report may trigger:</p> <ul><li>verification;</li> <li>voluntary precautions;</li> <li>clinical assessment;</li> <li>sample testing;</li> <li>consultation;</li> <li>readiness measures.</li></ul> <p>It does not by itself trigger detention, compulsory treatment, public naming, industrial closure, border restriction, or emergency declaration.</p> <h2>11.3 Reporter protection</h2> <p>Good-faith reporters require:</p> <ul><li>confidentiality where appropriate;</li> <li>anti-retaliation protection;</li> <li>correction pathways;</li> <li>protection against punishment for reasonable false alarms;</li> <li>clear distinctions between good-faith error, negligence, fabrication, and malicious interference.</li></ul> <h2>11.4 Sample and evidence provenance</h2> <p>Samples and derived data should record:</p> <ul><li>collector and authority;</li> <li>consent or lawful basis;</li> <li>time and place;</li> <li>chain of custody;</li> <li>processing and storage;</li> <li>laboratory methods;</li> <li>quality limitations;</li> <li>transfers;</li> <li>destruction, return, or archive rules;</li> <li>Indigenous, community, genetic, and protected-knowledge restrictions.</li></ul> <hr> <h1>12. Public-health rights baseline</h1> <p>Emergency health measures must preserve, to the maximum extent possible:</p> <ul><li>dignity and non-discrimination;</li> <li>bodily integrity;</li> <li>informed consent;</li> <li>accessible information;</li> <li>privacy and confidentiality;</li> <li>family and community contact;</li> <li>safe housing, food, water, sanitation, income, and care;</li> <li>legal counsel and challenge;</li> <li>disability accommodation;</li> <li>language access;</li> <li>religious and cultural practice consistent with necessary safety measures;</li> <li>continuity of unrelated medical care;</li> <li>child protection and best interests;</li> <li>protection from gender-based violence, coercion, exploitation, and retaliation;</li> <li>remedy for wrongful action.</li></ul> <p>Rights restrictions require a specific legal basis, evidence, necessity, proportionality, duration, review, and less-restrictive-alternative analysis.</p> <hr> <h1>13. Isolation, quarantine, movement, and gathering measures</h1> <h2>13.1 Voluntary support first</h2> <p>Authorities should first make compliance feasible through:</p> <ul><li>paid leave and income continuity;</li> <li>safe accommodation;</li> <li>food and medicine delivery;</li> <li>caregiving support;</li> <li>workplace protection;</li> <li>accessible communication;</li> <li>transport and shelter options;</li> <li>protection from eviction, dismissal, and discrimination.</li></ul> <h2>13.2 Compulsory measures</h2> <p>Compulsory isolation or quarantine requires:</p> <ul><li>valid law;</li> <li>individualized or legally defined criteria;</li> <li>reliable notice;</li> <li>clinical and evidentiary basis;</li> <li>humane conditions;</li> <li>time limits;</li> <li>periodic review;</li> <li>prompt challenge before an independent body;</li> <li>legal and language assistance;</li> <li>disability accommodation;</li> <li>compensation where law provides or where wrongful harm occurs.</li></ul> <p>Group or territorial measures require a documented explanation of why individualized or less restrictive measures are inadequate.</p> <h2>13.3 Community facilities</h2> <p>Community-supported isolation facilities must not become informal detention sites. Their governance should address consent, safeguarding, staffing, infection control, privacy, family contact, complaints, exit, and referral to clinical care.</p> <h2>13.4 Border measures</h2> <p>Travel and border measures require separate authority and should account for:</p> <ul><li>humanitarian movement;</li> <li>asylum and non-refoulement;</li> <li>returning residents;</li> <li>cross-border workers;</li> <li>medical evacuation;</li> <li>family unity;</li> <li>discriminatory impact;</li> <li>evidence that the measure meaningfully reduces risk.</li></ul> <hr> <h1>14. Vaccination, prophylaxis, and treatment</h1> <h2>14.1 Voluntary access</h2> <p>The primary obligation is to make safe, effective, accessible countermeasures genuinely available through:</p> <ul><li>transparent evidence;</li> <li>trusted and plural communication;</li> <li>informed consent;</li> <li>accessible venues;</li> <li>no-cost or affordable provision;</li> <li>paid time and adverse-event support;</li> <li>culturally appropriate delivery;</li> <li>independent safety monitoring.</li></ul> <h2>14.2 Requirements and conditions</h2> <p>Any vaccination or prophylaxis requirement must derive from valid law and specify:</p> <ul><li>covered setting and population;</li> <li>evidence of benefit and transmission relevance;</li> <li>medical and other legally required exceptions;</li> <li>alternative protective measures;</li> <li>duration and review;</li> <li>appeal;</li> <li>compensation for serious injury;</li> <li>protection against unrelated exclusion and stigma.</li></ul> <p>The framework does not authorize forced medical treatment.</p> <h2>14.3 Therapeutic decisions</h2> <p>Clinical treatment remains governed by professional standards, patient rights, consent, emergency medicine law, and scarce-resource rules. Emergency governance bodies may not prescribe treatment protocols solely through political vote or dashboard threshold.</p> <hr> <h1>15. Countermeasure allocation and scarce resources</h1> <h2>15.1 Lawful allocation mandate</h2> <p>A body allocating scarce diagnostics, vaccines, therapeutics, oxygen, protective equipment, beds, transport, or personnel must possess an explicit mandate and publish the applicable allocation rule.</p> <h2>15.2 Allocation criteria</h2> <p>Permissible criteria may include:</p> <ul><li>clinical need;</li> <li>expected benefit supported by evidence;</li> <li>exposure and occupational risk;</li> <li>transmission reduction;</li> <li>urgency;</li> <li>protection of essential care capacity;</li> <li>historical and structural disadvantage;</li> <li>geographic access;</li> <li>randomization among materially equivalent claims.</li></ul> <p>Impermissible criteria include social worth, wealth, political loyalty, GGF participation, nationality alone, disability stereotypes, developmental ranking, or ability to generate economic return.</p> <h2>15.3 Essential continuity</h2> <p>Allocation must protect:</p> <ul><li>primary and emergency care;</li> <li>maternal and reproductive health;</li> <li>disability and personal-assistance services;</li> <li>mental-health care;</li> <li>chronic medicines;</li> <li>palliative care;</li> <li>water, sanitation, food, shelter, and safe transport;</li> <li>worker protective equipment.</li></ul> <h2>15.4 Review and explanation</h2> <p>Allocation systems require:</p> <ul><li>reasons;</li> <li>conflict-of-interest controls;</li> <li>independent review;</li> <li>accessible complaint channels;</li> <li>audit for disparate impact;</li> <li>correction when forecasts or supplies change.</li></ul> <hr> <h1>16. Countermeasure research, production, and access</h1> <h2>16.1 Public-interest conditions</h2> <p>Publicly funded research and advance-purchase commitments should, where lawful, include conditions for:</p> <ul><li>affordable access;</li> <li>non-exclusive or shared licensing;</li> <li>transparent public investment;</li> <li>manufacturing transfer;</li> <li>regional production capacity;</li> <li>publication of clinically material evidence;</li> <li>safety and pharmacovigilance;</li> <li>fair compensation for research and production labour.</li></ul> <h2>16.2 Patent and licence powers</h2> <p>Compulsory licensing, patent use, patent pools, buyouts, procurement conditions, or public manufacture require valid intellectual-property, procurement, trade, Treaty, or domestic authority. The health coordination framework cannot create those powers by declaration.</p> <h2>16.3 Evidence transparency</h2> <p>Transparency should distinguish:</p> <ul><li>public clinical and regulatory evidence;</li> <li>confidential personal and patient information;</li> <li>protected Indigenous or community knowledge;</li> <li>legitimate manufacturing confidentiality;</li> <li>security-sensitive or dual-use details;</li> <li>information required by regulators, auditors, courts, or affected parties.</li></ul> <h2>16.4 Regional capacity</h2> <p>Capacity-building should support laboratories, manufacturing, quality assurance, cold chains, workforce education, maintenance, and supply resilience without creating technological dependency or extracting local data and biological materials.</p> <hr> <h1>17. Zoonotic and ecological-risk prevention</h1> <h2>17.1 Place-specific prevention</h2> <p>Jurisdictions may adopt evidence-based land-use, agricultural, occupational, wildlife, and ecosystem measures to reduce spillover risk. The framework does not designate global zones automatically.</p> <h2>17.2 Risk-sensitive area record</h2> <p>Any proposed risk-sensitive area should identify:</p> <ul><li>competent land and health authorities;</li> <li>ecological and epidemiological evidence;</li> <li>geographic method;</li> <li>affected residents, workers, landholders, and Indigenous nations;</li> <li>lawful activities and restrictions;</li> <li>subsistence and cultural protections;</li> <li>alternatives and transition support;</li> <li>monitoring authority;</li> <li>duration and review;</li> <li>compensation and remedy.</li></ul> <p>A universal fifty-kilometre perimeter is not presumed.</p> <h2>17.3 Indigenous territories</h2> <p>Indigenous territory is not automatically classified as a global health buffer. Measures require affected-nation authority and must respect self-government, access, subsistence, mobility, knowledge protection, and refusal of external monitoring.</p> <h2>17.4 Community monitoring</h2> <p>Community monitors should be protected and compensated through ordinary labour or grant arrangements. Their observations may have evidentiary value, but legal findings require the applicable evidentiary and adjudicative process.</p> <h2>17.5 Just transition</h2> <p>Where lawful regulation changes or closes harmful activity, workers and communities require income continuity, retraining, remediation, pension protection, local economic planning, and participation in the transition. AUBI Layer 1 remains unconditional.</p> <hr> <h1>18. Spillover bonds and industrial accountability</h1> <h2>18.1 Permissible use</h2> <p>A competent jurisdiction may use bonds, insurance, permit conditions, reserve requirements, or pooled compensation arrangements for defined high-risk activity.</p> <h2>18.2 Required design</h2> <p>A lawful scheme should specify:</p> <ul><li>covered activity and jurisdiction;</li> <li>risk model and uncertainty;</li> <li>amount and review method;</li> <li>operator and supply-chain duties;</li> <li>conditions for release or forfeiture;</li> <li>scientific assessment role;</li> <li>legal decision-maker;</li> <li>burden and standard of proof;</li> <li>appeal;</li> <li>worker and community continuity;</li> <li>use of proceeds;</li> <li>insolvency and cross-border enforcement.</li></ul> <p>No universal five-times-response-cost formula applies.</p> <h2>18.3 Causation</h2> <p>Genomic, epidemiological, geographic, temporal, occupational, ecological, and supply-chain evidence may inform causation. A scientific panel may provide an assessment but does not determine legal forfeiture, fault, or damages unless valid law expressly grants that adjudicative role with due-process safeguards.</p> <h2>18.4 No automatic seizure</h2> <p>A signal, assessment, or bond dispute does not by itself authorize asset freezing, market exclusion, or facility closure. Those actions require separate lawful authority and review.</p> <hr> <h1>19. Laboratory, biotechnology, and field-release incidents</h1> <h2>19.1 Interface with Aethelred</h2> <p>The Aethelred Accord governs biosafety standards, genetic rights, biotechnology access, release assessment, and incident preparedness within its valid legal interfaces. This framework governs population-health detection, clinical response, public-health assistance, and countermeasure allocation.</p> <p>Neither framework acquires residual authority over the other.</p> <h2>19.2 Incident handoff</h2> <p>A laboratory or biotechnology incident handoff should record:</p> <ul><li>facility and competent regulator;</li> <li>event and uncertainty;</li> <li>affected workers and communities;</li> <li>organism, construct, or material classification;</li> <li>containment status;</li> <li>health surveillance needs;</li> <li>data and sample restrictions;</li> <li>dual-use information limits;</li> <li>public communication responsibilities;</li> <li>evidence preservation;</li> <li>assistance requested;</li> <li>possible escalation under the Emergency Interface.</li></ul> <h2>19.3 Facility action</h2> <p>A laboratory pause, licence restriction, material seizure, or facility shutdown requires valid regulatory or judicial authority. Health observers and coordination secretariats may recommend action but cannot impose it.</p> <h2>19.4 Worker protection</h2> <p>Laboratory and production workers retain rights to hazard information, confidential medical assessment, exposure follow-up, paid leave, safe refusal, whistleblowing, representation, and compensation.</p> <hr> <h1>20. Antimicrobial resistance</h1> <h2>20.1 Bounded contribution</h2> <p>This framework contributes to AMR governance through:</p> <ul><li>community and clinical stewardship;</li> <li>treatment-failure reporting;</li> <li>occupational and agricultural risk reduction;</li> <li>procurement standards where lawfully adopted;</li> <li>access to diagnostics;</li> <li>public-interest antimicrobial research;</li> <li>environmental monitoring;</li> <li>cross-sector coordination.</li></ul> <p>It does not create a single global antibiotic regulator.</p> <h2>20.2 Sectoral interfaces</h2> <p>AMR requires cooperation among:</p> <ul><li>human-health authorities;</li> <li>veterinary and animal-welfare authorities;</li> <li>agriculture and food systems;</li> <li>environmental regulators;</li> <li>water and sanitation systems;</li> <li>professional bodies;</li> <li>pharmaceutical and research institutions;</li> <li>procurement agencies;</li> <li>workers and affected communities.</li></ul> <h2>20.3 Stewardship and access</h2> <p>Reducing inappropriate use must not deny necessary treatment. Stewardship systems should pair prescription quality with reliable diagnostic access, trained personnel, medicine availability, patient explanation, and review of discriminatory undertreatment.</p> <h2>20.4 Research and production</h2> <p>Antimicrobial innovation may require public or pooled funding, purchase commitments, stewardship conditions, manufacturing support, and access safeguards. Fiscal and intellectual-property powers must come from valid instruments.</p> <hr> <h1>21. Health data, surveillance, and privacy</h1> <p>Aurora Accord v1.3 controls data authority, classification, consent, fiduciary duties, cross-border transfer, protected non-transfer, deletion, and records.</p> <h2>21.1 Minimum necessary data</h2> <p>Health emergency data systems should collect the minimum information necessary for a specified public-health purpose and retain it only as long as lawfully needed.</p> <h2>21.2 Function separation</h2> <p>Data used for clinical care, contact support, public-health surveillance, research, law enforcement, immigration, employment, insurance, and intelligence should not flow between functions by default.</p> <h2>21.3 Contact and exposure systems</h2> <p>Systems require:</p> <ul><li>lawful basis;</li> <li>purpose limitation;</li> <li>non-digital alternative;</li> <li>no mandatory universal identity;</li> <li>security and access controls;</li> <li>correction;</li> <li>expiry and deletion;</li> <li>prohibition on unrelated commercial or political use;</li> <li>review of automated inference;</li> <li>protection from retaliation and stigma.</li></ul> <h2>21.4 Genetic and Indigenous data</h2> <p>Samples and genetic data may carry personal, relational, familial, collective, Indigenous-restricted, evidentiary, research, and public-health claims simultaneously. No registry or emergency declaration resolves these claims automatically.</p> <h2>21.5 Public dashboards</h2> <p>Dashboards must not expose individuals, vulnerable groups, protected locations, sensitive facilities, or knowledge whose publication increases harm. Aggregate statistics remain contestable and should disclose limitations.</p> <hr> <h1>22. Public information and communication</h1> <p>Synoptic Protocol v4.2 controls the epistemic-freedom and information-system interface.</p> <p>Health communication may:</p> <ul><li>provide warnings and practical guidance;</li> <li>explain evidence and uncertainty;</li> <li>correct material errors;</li> <li>publish reasons and review dates;</li> <li>translate and adapt format for language, disability, literacy, and channel;</li> <li>distinguish official instruction from scientific advice;</li> <li>acknowledge dissent and changed evidence.</li></ul> <p>It may not:</p> <ul><li>manufacture political narratives;</li> <li>classify communities by developmental worth;</li> <li>use covert psychographic persuasion;</li> <li>suppress lawful criticism merely because it reduces compliance or trust;</li> <li>present a model estimate as unquestionable fact;</li> <li>make criticism of a GGF institution evidence of misinformation.</li></ul> <p>Security-sensitive details may be withheld only under a lawful, reviewable basis. Secrecy cannot conceal rights violations, negligence, discrimination, or falsified evidence.</p> <hr> <h1>23. Conflict zones, humanitarian access, and health ceasefires</h1> <h2>23.1 Health-access arrangements</h2> <p>Health ceasefires, safe corridors, medical neutrality agreements, and humanitarian notification systems are negotiated arrangements, not unilateral declarations by a health council.</p> <h2>23.2 Consent and parties</h2> <p>Arrangements should involve:</p> <ul><li>competent conflict parties;</li> <li>affected communities;</li> <li>health providers;</li> <li>humanitarian actors;</li> <li>local and Indigenous authorities where applicable;</li> <li>neutral mediators;</li> <li>security and deconfliction specialists.</li></ul> <h2>23.3 Limits</h2> <p>Health actors may not:</p> <ul><li>confer immunity for war crimes or serious abuse;</li> <li>share patient or humanitarian data for targeting;</li> <li>condition care on political cooperation;</li> <li>become intelligence collectors;</li> <li>promise enforcement they do not control.</li></ul> <h2>23.4 Violations</h2> <p>Evidence of attacks on health workers, facilities, patients, or corridors should be preserved and handed to competent investigative and justice institutions. A coordination framework does not prosecute violations.</p> <hr> <h1>24. Workforce, care, and social continuity</h1> <h2>24.1 Protected workers</h2> <p>Emergency planning must include:</p> <ul><li>clinical and community health workers;</li> <li>laboratory and manufacturing workers;</li> <li>sanitation and waste workers;</li> <li>logistics and transport workers;</li> <li>carers and personal assistants;</li> <li>translators and accessibility workers;</li> <li>food, water, energy, housing, and communications workers;</li> <li>volunteers performing regular hazardous work.</li></ul> <h2>24.2 Minimum protections</h2> <p>Plans should cover:</p> <ul><li>wages and hazard compensation;</li> <li>staffing ratios and rest;</li> <li>protective equipment;</li> <li>occupational health;</li> <li>childcare and family support;</li> <li>disability accommodation;</li> <li>mental-health and trauma support;</li> <li>insurance and compensation;</li> <li>safe refusal;</li> <li>whistleblowing;</li> <li>collective representation;</li> <li>demobilisation and return to ordinary work.</li></ul> <h2>24.3 No compelled heroism</h2> <p>Public praise, Hearts, professional duty, patriotism, or emergency rhetoric cannot substitute for safe conditions and lawful employment obligations.</p> <h2>24.4 Care continuity</h2> <p>Emergency measures should prevent abandonment of people who depend on regular medication, dialysis, rehabilitation, reproductive care, mental-health services, personal assistance, home care, palliative care, or family caregiving.</p> <hr> <h1>25. Finance, procurement, and stockpiles</h1> <h2>25.1 Lawful sources</h2> <p>Funding may come from:</p> <ul><li>ordinary public budgets;</li> <li>lawful contingency reserves;</li> <li>valid Treaty or international funds;</li> <li>mutual-assistance agreements;</li> <li>grants and philanthropy with safeguards;</li> <li>lawfully adopted bonds, levies, insurance, or procurement conditions.</li></ul> <p>The framework creates no tax or automatic claim on the Global Commons Fund.</p> <h2>25.2 Pre-authorization</h2> <p>Rapid finance should rely on pre-authorized, objective, reviewable release conditions. A model threshold may release already appropriated support where the legal instrument so provides; it cannot create new fiscal authority.</p> <h2>25.3 Procurement safeguards</h2> <p>Emergency procurement requires:</p> <ul><li>need and price documentation;</li> <li>conflict-of-interest controls;</li> <li>anti-corruption review;</li> <li>quality assurance;</li> <li>labour and human-rights conditions;</li> <li>publication after security-sensitive periods;</li> <li>recovery of funds for fraud through lawful processes;</li> <li>no vendor control over public-health policy.</li></ul> <h2>25.4 Stockpiles</h2> <p>Stockpile plans should address rotation, expiry, maintenance, local suitability, accessibility, cold chain, distribution authority, theft and diversion, and equitable regional access.</p> <hr> <h1>26. WHO, regional, national, local, and Indigenous interfaces</h1> <h2>26.1 No functional migration by performance</h2> <p>Demonstrated competence may justify contracts, delegated functions, grants, partnership, or reform. It does not itself transfer authority from the WHO, a state, a municipality, a professional body, or an Indigenous nation.</p> <h2>26.2 Agreement-based interfaces</h2> <p>Interfaces should identify:</p> <ul><li>the participating institutions;</li> <li>the function being shared or delegated;</li> <li>legal authority;</li> <li>decision and command boundaries;</li> <li>data and confidentiality;</li> <li>finance and procurement;</li> <li>liability and remedy;</li> <li>duration, withdrawal, and review;</li> <li>records and public explanation.</li></ul> <h2>26.3 WHO relationship</h2> <p>The framework may complement WHO functions, use WHO technical work, support implementation of applicable international health obligations, and participate in lawful agreements. It does not establish a competing global health authority.</p> <h2>26.4 Indigenous health authority</h2> <p>Indigenous nations determine their own representation and may:</p> <ul><li>establish direct health agreements;</li> <li>accept or refuse outside assistance;</li> <li>protect knowledge and samples;</li> <li>control territorial access;</li> <li>maintain their own health and emergency law;</li> <li>require culturally safe services;</li> <li>negotiate cross-border and regional interfaces.</li></ul> <p>No universal Indigenous council speaks for all peoples.</p> <hr> <h1>27. Interface with the Planetary Immune System</h1> <p>PIS v2.2.2 provides catastrophic-risk foresight, readiness, dependency mapping, exercises, and bounded coordination. It does not take over health governance.</p> <h2>27.1 Permitted PIS support</h2> <p>PIS may support:</p> <ul><li>cross-domain state estimates;</li> <li>cascading-failure analysis;</li> <li>option and dependency mapping;</li> <li>exercises;</li> <li>identification of capability gaps;</li> <li>coordination among separately authorized response modules;</li> <li>continuity planning.</li></ul> <h2>27.2 No automatic escalation</h2> <p>An outbreak’s size, fatality estimate, geographic spread, or modelled catastrophic potential does not automatically transfer health authority to PIS.</p> <h2>27.3 Activation</h2> <p>Any PIS-linked action must follow the Emergency Interface and identify:</p> <ul><li>competent declarer;</li> <li>specific activated module;</li> <li>mission command;</li> <li>host consent or other valid authority;</li> <li>rights and non-derogation;</li> <li>review and termination;</li> <li>restoration and compensation.</li></ul> <h2>27.4 Non-escalation</h2> <p>The lawful result may be:</p> <ul><li>continued observation;</li> <li>local or national action;</li> <li>voluntary assistance;</li> <li>ordinary regulation;</li> <li>no foreign deployment;</li> <li>no PIS coordination;</li> <li>unresolved status.</li></ul> <hr> <h1>28. Justice, evidence, liability, and remedy</h1> <p>Justice Systems v1.4 controls jurisdiction, standing, evidence, due process, interim measures, remedies, appeal, recognition, and enforcement.</p> <h2>28.1 Separation</h2> <p>Health assessors, coordination secretariats, field teams, regulators, laboratories, and community networks do not adjudicate their own contested actions.</p> <h2>28.2 Evidence handoff</h2> <p>A handoff should identify:</p> <ul><li>source and authority;</li> <li>chain of custody;</li> <li>methods and uncertainty;</li> <li>personal, genetic, Indigenous, confidential, and security restrictions;</li> <li>exculpatory and dissenting material;</li> <li>requested legal action;</li> <li>continuing health needs.</li></ul> <h2>28.3 Remedies</h2> <p>Possible remedies under valid law may include:</p> <ul><li>cessation or modification of unlawful measures;</li> <li>release from wrongful isolation;</li> <li>correction of records;</li> <li>compensation;</li> <li>medical care and rehabilitation;</li> <li>employment restoration;</li> <li>return or deletion of data and samples;</li> <li>community remediation;</li> <li>apology or restorative process where voluntarily chosen;</li> <li>institutional reform;</li> <li>disciplinary, civil, administrative, or criminal action.</li></ul> <h2>28.4 No denial of care as sanction</h2> <p>Essential care, AUBI Layer 1, personal balances, food, shelter, legal access, and emergency assistance may not be withheld as punishment for non-participation, criticism, data refusal, or inability to comply.</p> <hr> <h1>29. Termination, restoration, and ordinary-law transition</h1> <h2>29.1 Termination</h2> <p>Every activated measure requires termination criteria. At termination, responsible institutions should issue an <strong>Emergency Termination Certificate</strong> identifying:</p> <ul><li>powers ended;</li> <li>continuing ordinary functions;</li> <li>personnel demobilisation;</li> <li>facility return;</li> <li>procurement closeout;</li> <li>data disposition;</li> <li>outstanding claims;</li> <li>unresolved health risks.</li></ul> <h2>29.2 Authority return</h2> <p>Temporary coordination, delegated functions, credentials, facilities, equipment, and data access return to their lawful holders unless a separate ordinary legal act provides otherwise.</p> <h2>29.3 Data and samples</h2> <p>Post-emergency review must determine whether data and samples are:</p> <ul><li>retained under valid health or research law;</li> <li>returned;</li> <li>transferred under a new authority;</li> <li>anonymized where genuinely possible;</li> <li>archived with restrictions;</li> <li>destroyed;</li> <li>subject to correction or deletion.</li></ul> <p>Emergency collection does not create perpetual research or commercial rights.</p> <h2>29.4 Persistent conditions</h2> <p>When a condition persists beyond extraordinary time limits, authorities should move required measures into ordinary health, labour, environmental, social-protection, procurement, or infrastructure law.</p> <h2>29.5 Wrongful action</h2> <p>People and communities harmed by false alarms, wrongful restrictions, negligent response, discriminatory allocation, unsafe work, data misuse, or unnecessary facility action need accessible claims and compensation pathways.</p> <hr> <h1>30. Learning, metrics, and anti-Goodhart safeguards</h1> <h2>30.1 Learning goals</h2> <p>Evaluation should ask:</p> <ul><li>Was the event detected early enough?</li> <li>Were observations independent and limitations visible?</li> <li>Did lawful authority match actual action?</li> <li>Were rights and essential care preserved?</li> <li>Were local and Indigenous capacities respected?</li> <li>Did workers have safe conditions?</li> <li>Was assistance useful and requested?</li> <li>Were countermeasures allocated fairly?</li> <li>Did measures reduce harm relative to alternatives?</li> <li>Were false alarms and overreaction managed without retaliation?</li> <li>Did temporary authority end?</li> <li>What ordinary capacity should change?</li></ul> <h2>30.2 Metrics as evidence, not switches</h2> <p>Metrics may inform learning and pre-authorized support. They do not automatically declare emergencies, impose restrictions, punish jurisdictions, or establish liability.</p> <h2>30.3 Suggested measures</h2> <p>Possible measures include:</p> <ul><li>detection and verification time;</li> <li>continuity of essential care;</li> <li>worker injury and burnout;</li> <li>accessibility and language coverage;</li> <li>supply availability;</li> <li>distribution equity;</li> <li>rights challenges and outcomes;</li> <li>false-positive and false-negative consequences;</li> <li>outbreak size and severity adjusted for context;</li> <li>local capacity retained after assistance;</li> <li>data deletion and restoration completion;</li> <li>time to return authority.</li></ul> <p>Targets such as “zero outbreaks,” universal trust, fixed compliance, or required risk findings may conceal under-reporting, coercion, or gaming.</p> <h2>30.4 Dissent and failure</h2> <p>After-action reports must preserve dissent, adverse findings, and the possibility that:</p> <ul><li>the risk was overstated;</li> <li>the preferred model was wrong;</li> <li>no emergency declaration was necessary;</li> <li>a restriction caused more harm than it prevented;</li> <li>local action outperformed external deployment;</li> <li>an institution should narrow, transfer, or dissolve.</li></ul> <hr> <h1>31. Implementation, pilots, and first seating</h1> <h2>31.1 Pre-authorization pilots</h2> <p>Before Treaty or domestic adoption, permissible pilots include:</p> <ul><li>community health training;</li> <li>offline reporting and radio exercises;</li> <li>voluntary stockpile coordination;</li> <li>accessibility and translation;</li> <li>non-binding state estimation;</li> <li>laboratory and health handoff simulations;</li> <li>worker-safety planning;</li> <li>voluntary mutual-aid agreements;</li> <li>countermeasure-allocation tabletop exercises;</li> <li>data-deletion and restoration tests.</li></ul> <p>Pilots may not impose quarantine, compulsory vaccination, industry closure, asset seizure, market exclusion, or foreign deployment without existing lawful authority.</p> <h2>31.2 Genesis alignment</h2> <p>Institutional formation follows Genesis v0.9:</p> <ul><li>design does not constitute authority;</li> <li>demonstration is not jurisdiction;</li> <li>first seating follows the constituting instrument;</li> <li>founder, funder, and vendor control must terminate or transfer;</li> <li>coercive powers remain inactive until separately authorized;</li> <li>failure, non-scaling, redesign, or dissolution are legitimate.</li></ul> <h2>31.3 Biological-risk joint work</h2> <p>Global Health v2.2.2 and Aethelred v1.2.2 should jointly test:</p> <ul><li>a small laboratory incident with global propagation potential;</li> <li>a field-release concern with disputed causation;</li> <li>a zoonotic cluster of unknown origin;</li> <li>a false-positive pandemic alert;</li> <li>a dual-use information dispute;</li> <li>a genetic-data non-transfer decision;</li> <li>a countermeasure shortage;</li> <li>a host jurisdiction refusing foreign deployment;</li> <li>a responder safety refusal;</li> <li>an emergency extending beyond ninety days.</li></ul> <h2>31.3A Cross-domain event and Global Health–Aethelred coordination</h2> <p>Global Health adopts the Emergency Cross-Domain Event Envelope v0.1 (<code>CDEE/0.1</code>) for compound-event identity and adopts the Global Health–Aethelred Biological Incident Coordination Addendum v0.1 (<code>GH-AE-BICA/0.1</code>) when an incident engages Aethelred functions.</p> <blockquote><p><strong>Global Health–Aethelred coordination.</strong> When a biological incident engages functions governed by Aethelred Accord v1.2.2, this framework uses <code>GH-AE-BICA/0.1</code> and <code>CDEE/0.1</code> for shared event identity, function-level responsibility, handoff, custody, review, and closure. The Addendum does not transfer health authority, create facility jurisdiction, or replace ECRC authority and rights records.</p></blockquote> <p>The Addendum assigns functions rather than the whole event. Population-health observation, clinical response, health measures, countermeasure allocation, essential-care continuity, and health communication remain with competent health authorities. Facility containment, construct and release assessment, provenance, dual-use controls, and manufacturing biosafety remain with competent Aethelred authorities. Origin assessment, worker protection, sample custody, public communication, and closure may be concurrent without becoming joint command.</p> <h2>31.4 Adoption</h2> <p>Jurisdictions may adopt components independently. Participation in assessment, logistics, stockpiles, community networks, or research does not imply consent to compulsory emergency powers.</p> <hr> <h1>32. Amendment, withdrawal, continuity, and dissolution</h1> <h2>32.1 Amendment classes</h2> <p>Changes should distinguish:</p> <ul><li>technical guidance;</li> <li>operational procedures;</li> <li>institutional charters;</li> <li>rights protections;</li> <li>fiscal instruments;</li> <li>coercive powers;</li> <li>Treaty amendments.</li></ul> <p>A technical update cannot amend a right or create jurisdiction.</p> <h2>32.2 Withdrawal</h2> <p>A participant may withdraw according to the governing agreement, subject to safe continuity of active patient care, lawful obligations, records, workers, and ongoing claims.</p> <h2>32.3 Continuity</h2> <p>Institutional closure requires plans for:</p> <ul><li>active cases and patients;</li> <li>samples and health records;</li> <li>stockpiles and equipment;</li> <li>personnel and accrued rights;</li> <li>contracts and procurement;</li> <li>unresolved alerts;</li> <li>complaints and compensation;</li> <li>protected knowledge;</li> <li>public communication.</li></ul> <h2>32.4 Dissolution</h2> <p>No health coordination institution is presumed permanent. It may dissolve without a successor where functions are no longer needed or are better held elsewhere. Dissolution does not extinguish rights, claims, archival duties, or protected data obligations.</p> <hr> <h1>33. Constitutional readiness gates</h1> <p>A binding or coercive component is not ready unless all applicable gates pass.</p> <ol><li><strong>Source-of-authority gate:</strong> the competent legal instrument is identified.</li> <li><strong>Function-separation gate:</strong> observation, declaration, logistics, regulation, adjudication, and enforcement are separated.</li> <li><strong>Declaration gate:</strong> emergency declaration criteria, scope, duration, and review are defined.</li> <li><strong>Power-specific activation gate:</strong> no blanket emergency activation exists.</li> <li><strong>Host-authority gate:</strong> foreign or cross-border assistance has a valid entry and command basis.</li> <li><strong>Rights gate:</strong> bodily integrity, liberty, privacy, accessibility, counsel, and remedy are operationalized.</li> <li><strong>Health-support gate:</strong> voluntary compliance is materially feasible before coercion is considered.</li> <li><strong>Isolation gate:</strong> humane conditions, review, and challenge exist.</li> <li><strong>Vaccination gate:</strong> evidence, exceptions, alternatives, review, and injury support exist.</li> <li><strong>Allocation gate:</strong> scarce-resource criteria and appeal are explicit.</li> <li><strong>Worker gate:</strong> wages, safety, refusal, insurance, and demobilisation are protected.</li> <li><strong>Indigenous-authority gate:</strong> affected nations control their interfaces and protected knowledge.</li> <li><strong>Data gate:</strong> Aurora-compliant authority, minimization, separation, expiry, and deletion exist.</li> <li><strong>Evidence gate:</strong> provenance, uncertainty, exculpatory material, and chain of custody are preserved.</li> <li><strong>Laboratory handoff gate:</strong> health and biosafety responsibilities are distinguished.</li> <li><strong>Industrial-action gate:</strong> scientific assessment is separated from legal liability and enforcement.</li> <li><strong>Finance gate:</strong> funding and procurement rest on valid instruments.</li> <li><strong>Communication gate:</strong> warnings and corrections are separated from propaganda and covert persuasion.</li> <li><strong>Time gate:</strong> 72-hour, 30-day, and 90-day reviews are implemented.</li> <li><strong>Termination gate:</strong> authority return, asset return, and data disposition are planned.</li> <li><strong>Compensation gate:</strong> wrongful-action claims are accessible.</li> <li><strong>Ordinary-law gate:</strong> persistent conditions transition out of emergency governance.</li> <li><strong>Non-participation gate:</strong> refusal to join a GGF programme is not sanctionable.</li> <li><strong>Failure gate:</strong> the system can conclude non-escalation, insufficient evidence, redesign, or dissolution.</li></ol> <hr> <h1>34. Operational records</h1> <h2>Record inheritance and conformance</h2> <ol><li><p><strong>Specialization does not replace the canonical set.</strong><br> This framework’s domain record list specializes but does not replace the records defined by the Emergency, Catastrophic-Risk, and Continuity Interface Specification and the Emergency and Catastrophic-Risk Cluster Record Profile. Every canonical record remains required whenever its applicability trigger occurs.</p></li> <li><p><strong>Canonical identity.</strong><br> Every domain record shall identify the canonical <code>ECRC-##</code> record or records it <code>implements</code>, <code>extends</code>, <code>splits</code>, <code>contains</code>, or <code>imports</code>. A domain label may differ from the canonical title, but the canonical identifier, schema version, minimum common header, legal effect, access protections, and lifecycle obligations remain traceable.</p></li> <li><p><strong>Direct import.</strong><br> A canonical record not mapped to a domain specialization is imported directly when triggered. Absence from a domain appendix, implementation guide, software form, dashboard, or local registry does not make the canonical record optional.</p></li> <li><p><strong>Non-applicability.</strong><br> A record may be marked <code>not_applicable</code> only through a reasoned, event- or action-specific determination identifying: the trigger tested; the deciding function; the evidence and legal basis; the reason the trigger cannot arise or has not arisen; the records that would become required if conditions change; and the review or expiry condition. <code>Not applicable</code> does not mean unknown, inconvenient, deferred, or unavailable.</p></li> <li><p><strong>Split records.</strong><br> Where several domain records jointly implement one canonical record, the framework shall declare a <code>splits</code> relationship, identify every component, allocate each required canonical field, designate the function that verifies completeness, and preserve one traceable lifecycle. No component inherits the authority or legal effect of another by implication.</p></li> <li><p><strong>Containing packages.</strong><br> A domain package may contain several canonical records only when each canonical subrecord remains separately identifiable, reviewable, correctable, exportable, and closable, with its own responsible authority, legal effect, timestamp, expiry, and access class. The Investigation and Evidence Handoff Record (<code>ECRC-24</code>) and the Adjudication and Enforcement Handoff Record (<code>ECRC-25</code>) shall remain distinct even when displayed in one user interface or transmitted in one package.</p></li> <li><p><strong>No record-to-power conversion.</strong><br> A record name, canonical identifier, completed form, model output, dashboard state, validation result, digital signature, institutional endorsement, or reference to another framework does not create authority. Consequential action requires a valid Emergency Authority Provenance Record (<code>ECRC-06</code>) and every other record required by the applicable activation package.</p></li> <li><p><strong>Shared event identity without shared command.</strong><br> Records participating in a compound or cross-domain event shall carry the same <code>cluster_event_id</code> and identify their responsible function, authority, handoff state, evidence or data custodian, review time, and closure state. Shared identity coordinates information; it does not merge jurisdictions, transfer command, or establish a common legal classification.</p></li> <li><p><strong>Handoff acceptance and retained duties.</strong><br> A handoff is effective only when the receiving function records acceptance, rejection, deficiency, or concurrent responsibility. A handoff transfers only the responsibility expressly named. It does not erase the sender’s retained duties, source obligations, correction duties, evidence-preservation duties, or responsibility for prior acts.</p></li> <li><p><strong>Lifecycle completeness.</strong><br> Any activation package that can restrict rights, deploy personnel or assets, process emergency data, spend extraordinary funds, or continue beyond a provisional period shall also represent renewal, termination, authority and asset restoration, emergency-data disposition, wrongful-action remedy, after-action review, institutional sunset or continuation, and unresolved risk or dissent. A package is not closed merely because a declaration or mission has ended.</p></li> <li><p><strong>Access and protected material.</strong><br> Canonical identity does not require universal publication. Public summaries, protected annexes, restricted operational records, protected sovereignty or source records, and sealed adjudicative or security material shall follow the access classes in <code>ECRC/0.1</code>. Indigenous authority, non-engagement, protected knowledge, source protection, privacy, security, correction, retention, deletion, return, repatriation, and non-transfer obligations survive transport between frameworks.</p></li> <li><p><strong>Correction, supersession, and integrity.</strong><br> Record identifiers remain immutable. Corrections, withdrawals, supersession, invalidation, and disputes shall preserve the prior state, reason, responsible actor, time, and linked replacement. Hashes and automated validation may support integrity but do not prove authenticity, accuracy, legal validity, or authority.</p></li> <li><p><strong>Precedence and conflict.</strong><br> Where a domain record conflicts with the canonical profile, the rule that better preserves valid authority provenance, functional separation, rights, protected knowledge, temporal limits, restoration, and review controls for cluster interoperability controls. A domain framework may impose stronger safeguards. It may not weaken the canonical safeguards through renaming, omission, aggregation, software implementation, or local practice.</p></li> <li><p><strong>Version pinning.</strong><br> This framework conforms only to the exact profile and interface versions identified in its compatibility manifest. A later framework, profile, schema, or interface version is not substituted automatically. Material changes fail closed until a successful compatibility and scenario test is recorded.</p></li> <li><p><strong>Conformance appendix.</strong><br> This framework shall publish a complete crosswalk for <code>ECRC-01</code> through <code>ECRC-33</code>, showing for each canonical record: domain record name; inheritance relationship; applicability rule; responsible function; default access class; required linked records; lifecycle closure; and any current gap. Conformance is not established by a general statement that another framework controls.</p></li> <li><p><strong>Automated systems.</strong><br> Automated systems may check schema, completeness, links, expiry, consistency, signatures, and access rules. They may not determine whether an authority is legally valid, whether evidence is credible, whether a person is liable or guilty, whether an Indigenous authority has consented, or whether an emergency power should be exercised or renewed.</p></li> <li><p><strong>Failure rule.</strong><br> Missing, invalid, expired, incompatible, or unresolved authority and lifecycle records block the affected consequential action. They do not transfer authority to a coordinating body, observatory, emergency council, court, fund, platform, model, or residual command.</p></li></ol> <blockquote><p><strong>Framework conformance statement:</strong> Global Health Preparedness, Outbreak Response, and Biosecurity Framework v2.2.2 adopts Emergency Record Inheritance Clause v0.1 and conforms to Emergency and Catastrophic-Risk Cluster Record Profile v0.1 only to the extent shown in its complete ECRC-01–ECRC-33 crosswalk. Unmapped records are imported directly when triggered. Recorded gaps block the affected consequential action until resolved.</p></blockquote> <h2>Domain operational records</h2> <p>The framework uses the domain records below. Renaming, splitting, or containing records is permitted only through the declared inheritance relationships and completeness rules in <code>ECRC-RIC/0.1</code>.</p> <ol><li>Health Threat Signal Record</li> <li>Biological-Risk Profile</li> <li>Observation Independence Map</li> <li>Sample and Evidence Provenance Record</li> <li>Incident-Origin and Confidence Record</li> <li>Health State Estimate and Dissent Record</li> <li>Emergency Declaration Record</li> <li>Emergency Authority Provenance Record</li> <li>Power Activation Schedule</li> <li>Host Request and Assistance Acceptance Record</li> <li>Mission Scope and Command Record</li> <li>Community Health Network Charter</li> <li>Health Emergency Assistance Corps Deployment Record</li> <li>Health Worker and Responder Safety Record</li> <li>Rights and Less-Restrictive-Means Record</li> <li>Isolation or Quarantine Review Record</li> <li>Vaccination or Prophylaxis Requirement Record</li> <li>Countermeasure Evidence and Authorization Record</li> <li>Countermeasure Allocation and Equity Record</li> <li>Essential Care Continuity Record</li> <li>Health-Data Authority and Access Record</li> <li>Contact and Exposure Data Expiry Record</li> <li>Indigenous Health and Protected-Knowledge Interface Record</li> <li>Laboratory or Field-Release Handoff Record</li> <li>Dual-Use Information Review Record</li> <li>Risk-Sensitive Area and Land-Use Record</li> <li>Spillover Bond or Industrial Assurance Record</li> <li>Public Information and Correction Record</li> <li>Conflict-Zone Health Access Record</li> <li>Finance, Procurement, and Stockpile Record</li> <li>Investigation and Evidence Handoff Record</li> <li>Adjudication and Enforcement Handoff Record</li> <li>Renewal Health State Estimate</li> <li>Emergency Termination Certificate</li> <li>Authority, Facility, and Asset Return Record</li> <li>Health Data and Sample Disposition Record</li> <li>Wrongful Action and Compensation Record</li> <li>After-Action and Ordinary-Capacity Review</li> <li>Institutional Continuation, Transfer, or Dissolution Record</li></ol> <hr> <h1>35. Conclusion</h1> <p>Global health security is strongest when communities can detect danger, workers are protected, public institutions can cooperate rapidly, supplies are available, evidence remains contestable, and emergency powers are already bounded before fear and urgency arrive.</p> <p>The successor therefore replaces the image of one global immune system commanded from above with a <strong>federated ecology of health capacity</strong>:</p> <ul><li>local and Indigenous health authority;</li> <li>regional and international cooperation;</li> <li>independent observation;</li> <li>requested assistance;</li> <li>lawful public-health powers;</li> <li>equitable countermeasure systems;</li> <li>accountable regulation;</li> <li>independent justice;</li> <li>explicit termination and restoration.</li></ul> <p>A fast response is not one that skips constitutional interfaces. It is one that built them in advance.</p> <hr> <h1>Appendix A. Biological-Risk Profile — minimum fields</h1> <ul><li>event identifier;</li> <li>origin classes and confidence;</li> <li>event-status class;</li> <li>affected populations and territories;</li> <li>pathogen, organism, construct, or syndrome where known;</li> <li>transmission and exposure hypotheses;</li> <li>severity and uncertainty;</li> <li>observation sources and dependencies;</li> <li>health-system and supply dependencies;</li> <li>Indigenous, community, occupational, and ecological interfaces;</li> <li>plausible action and inaction harms;</li> <li>competent authorities;</li> <li>review time.</li></ul> <h1>Appendix B. Emergency Authority Provenance Record — health fields</h1> <ul><li>legal source;</li> <li>declarer;</li> <li>activated power;</li> <li>territory and population;</li> <li>factual predicate;</li> <li>necessity and proportionality;</li> <li>less restrictive alternatives;</li> <li>responsible operator;</li> <li>review body;</li> <li>start and expiry;</li> <li>rights affected;</li> <li>excluded powers;</li> <li>termination and compensation route.</li></ul> <h1>Appendix C. Community Health Network Charter — minimum fields</h1> <ul><li>constituting authority;</li> <li>voluntary, employment, and professional roles;</li> <li>clinical and non-clinical boundaries;</li> <li>training and supervision;</li> <li>wages, insurance, and safety;</li> <li>data and confidentiality;</li> <li>Indigenous and community authority;</li> <li>complaint and whistleblowing;</li> <li>emergency and ordinary functions;</li> <li>dissolution and records.</li></ul> <h1>Appendix D. Health Emergency Assistance Corps Deployment Record</h1> <ul><li>request or authorization;</li> <li>host institution;</li> <li>mission and excluded tasks;</li> <li>personnel and credentials;</li> <li>command and professional accountability;</li> <li>facilities and supply authority;</li> <li>data and sample rules;</li> <li>security arrangements;</li> <li>immunity and claims;</li> <li>worker protections;</li> <li>public communication;</li> <li>termination and handback.</li></ul> <h1>Appendix E. Isolation or Quarantine Review Record</h1> <ul><li>legal basis;</li> <li>person or class affected;</li> <li>evidence and infectious period;</li> <li>voluntary support attempted;</li> <li>less restrictive alternatives;</li> <li>conditions and services;</li> <li>notice and counsel;</li> <li>review date;</li> <li>release criteria;</li> <li>challenge and compensation.</li></ul> <h1>Appendix F. Countermeasure Allocation and Equity Record</h1> <ul><li>resource and scarcity;</li> <li>allocation mandate;</li> <li>evidence and objectives;</li> <li>priority criteria;</li> <li>impermissible criteria;</li> <li>accessibility and geographic access;</li> <li>conflict-of-interest review;</li> <li>individual explanation where applicable;</li> <li>appeal and correction;</li> <li>distribution outcomes and disparities.</li></ul> <h1>Appendix G. Laboratory or Field-Release Handoff Record</h1> <ul><li>incident source;</li> <li>biosafety and health authorities;</li> <li>affected workers and communities;</li> <li>material and containment status;</li> <li>health surveillance;</li> <li>evidence custody;</li> <li>dual-use restrictions;</li> <li>data and sample authority;</li> <li>requested health response;</li> <li>possible PIS support;</li> <li>review and termination.</li></ul> <h1>Appendix H. Risk-Sensitive Area and Land-Use Record</h1> <ul><li>jurisdiction and land authority;</li> <li>affected Indigenous nations and rights holders;</li> <li>ecological and epidemiological evidence;</li> <li>geographic method;</li> <li>activities affected;</li> <li>transition and compensation;</li> <li>monitoring;</li> <li>duration and review;</li> <li>enforcement authority;</li> <li>remedies.</li></ul> <h1>Appendix I. Wrongful Action and Compensation Record</h1> <ul><li>action and authority;</li> <li>claimant and standing;</li> <li>alleged harm;</li> <li>urgent restoration need;</li> <li>evidence and records;</li> <li>responsible institution;</li> <li>interim support;</li> <li>adjudication or settlement route;</li> <li>compensation and rehabilitation;</li> <li>institutional correction;</li> <li>public reporting with privacy safeguards.</li></ul> <h1>Appendix J. Joint Global Health–Aethelred test suite</h1> <ol><li>uncertain zoonotic cluster near industrial agriculture;</li> <li>laboratory exposure with no confirmed community transmission;</li> <li>disputed gene-drive escape signal;</li> <li>false-positive genomic alarm;</li> <li>restricted Indigenous genetic sample requested for public-health research;</li> <li>shortage of vaccine and diagnostic manufacturing inputs;</li> <li>dual-use method needed for defence but dangerous if fully public;</li> <li>health emergency during a cyber outage;</li> <li>foreign assistance requested by a hospital but refused by the competent state authority;</li> <li>response continuing beyond ninety days;</li> <li>wrongful quarantine and data-retention claim;</li> <li>after-action finding that non-escalation was correct.</li></ol> <hr> <h1>Appendix K. ECRC-01–ECRC-33 conformance crosswalk</h1> <blockquote><p><strong>Conformance statement:</strong> Global Health Preparedness, Outbreak Response, and Biosecurity Framework v2.2.2 adopts Emergency Record Inheritance Clause v0.1 and conforms to Emergency and Catastrophic-Risk Cluster Record Profile v0.1 only to the extent shown in its complete ECRC-01–ECRC-33 crosswalk. Unmapped records are imported directly when triggered. Recorded gaps block the affected consequential action until resolved.</p></blockquote> <p><strong>Pinned compatibility:</strong> Emergency, Catastrophic-Risk, and Continuity Interface Specification v0.1; Emergency and Catastrophic-Risk Cluster Record Profile v0.1 (<code>ECRC/0.1</code>); Emergency Record Inheritance Clause v0.1 (<code>ECRC-RIC/0.1</code>).</p> <table><thead><tr><th>Canonical</th><th>Domain record</th><th>Relationship</th><th>Applicability trigger</th><th>Responsible function</th><th>Access</th><th>Required links</th><th>Closure</th><th>Current gap</th></tr></thead><tbody><tr><td><code>ECRC-01</code> Hazard Alert Record</td><td>Health Threat Signal Record</td><td><code>extends</code></td><td>A person, sensor, institution, or protected source reports a condition that may require assessment.</td><td>alert-receipt and source-protection function</td><td>AC-2</td><td>ECRC-03 when assessed; ECRC-19 when sensitive data are processed</td><td>Closed by assessment, withdrawal, merger with traceable provenance, or archival disposition.</td><td>none</td></tr><tr><td><code>ECRC-02</code> Observation Contract</td><td>direct canonical import</td><td><code>imports</code></td><td>An observation programme, model, dashboard, monitoring network, laboratory, or assessment process is commissioned or relied upon.</td><td>observation commissioning and governance function</td><td>AC-2</td><td>ECRC-04; ECRC-19; ECRC-20 when protected knowledge is involved</td><td>Closed by expiry, replacement, suspension, or documented termination and data disposition.</td><td>none — direct import applies when triggered</td></tr><tr><td><code>ECRC-03</code> Catastrophic-Risk State Estimate</td><td>Health State Estimate and Dissent Record</td><td><code>extends</code></td><td>A decision-relevant hazard or system condition requires a structured estimate.</td><td>independent state-estimation function</td><td>AC-2</td><td>ECRC-01; ECRC-02; ECRC-04; ECRC-05 when jurisdiction is implicated</td><td>Superseded by a later estimate, closed by resolved question, or archived with unresolved status in ECRC-33.</td><td>none</td></tr><tr><td><code>ECRC-04</code> Observation Independence Map</td><td>Observation Independence Map</td><td><code>implements</code></td><td>A state estimate or monitoring system depends on multiple observers, models, laboratories, or data providers.</td><td>assessment-independence review function</td><td>AC-2</td><td>ECRC-02; ECRC-03</td><td>Updated whenever material observers, dependencies, or conflicts change.</td><td>none</td></tr><tr><td><code>ECRC-05</code> Standing and Jurisdiction Map</td><td>direct canonical import</td><td><code>imports</code></td><td>A condition may affect multiple territories, peoples, sectors, professional regulators, or legal decision classes.</td><td>standing and jurisdiction-mapping function</td><td>AC-2</td><td>ECRC-03; ECRC-06; ECRC-10; ECRC-11</td><td>Closed only when all active functions have an identified authority or an explicit authority gap is recorded.</td><td>none — direct import applies when triggered</td></tr><tr><td><code>ECRC-06</code> Emergency Authority Provenance Record</td><td>Emergency Authority Provenance Record</td><td><code>implements</code></td><td>Any consequential emergency act, declaration, deployment, restriction, compulsory measure, seizure, or extraordinary expenditure is proposed.</td><td>competent authority-provenance verification function</td><td>AC-2</td><td>ECRC-05; ECRC-07 when declaration is required; ECRC-08; ECRC-13</td><td>Expires with the power, is superseded by a new valid record, or is invalidated and routed to restoration.</td><td>none</td></tr><tr><td><code>ECRC-07</code> Emergency Declaration Record</td><td>Emergency Declaration Record</td><td><code>implements</code></td><td>Applicable law requires a formal declaration before specified emergency powers or resources may be used.</td><td>lawful declaring authority</td><td>AC-1</td><td>ECRC-03; ECRC-05; ECRC-06; ECRC-08</td><td>Closed by expiry, withdrawal, judicial invalidation, replacement, or ECRC-27.</td><td>none</td></tr><tr><td><code>ECRC-08</code> Power Activation and Prohibition Schedule</td><td>Power Activation Schedule</td><td><code>extends</code></td><td>A valid authority proposes to activate one or more specific emergency powers.</td><td>power-specific activating authority</td><td>AC-2</td><td>ECRC-06; ECRC-07 when applicable; ECRC-09; ECRC-13; ECRC-22</td><td>Each power closes separately by expiry, termination, invalidation, or replacement.</td><td>none</td></tr><tr><td><code>ECRC-09</code> Operational Command and Deployment Record</td><td>Mission Scope and Command Record / Health Emergency Assistance Corps Deployment Record</td><td><code>splits</code></td><td>Personnel, assets, facilities, or operational modules are deployed or coordinated.</td><td>authorized operational command function</td><td>AC-3</td><td>ECRC-06; ECRC-08; ECRC-10; ECRC-16; ECRC-23 when assistance crosses boundaries</td><td>Closed by mission termination, handoff acceptance, demobilisation, and verified asset/credential return.</td><td>none</td></tr><tr><td><code>ECRC-10</code> Host and Territorial Authorization Record</td><td>Host Request and Assistance Acceptance Record</td><td><code>extends</code></td><td>Assistance, deployment, access, facility use, data collection, or operations occur in another territory or under another host authority.</td><td>host and territorial authorization function</td><td>AC-2</td><td>ECRC-05; ECRC-09; ECRC-11 where Indigenous territory is affected; ECRC-23</td><td>Closed by withdrawal, expiry, completion, revocation, or verified handback.</td><td>none</td></tr><tr><td><code>ECRC-11</code> Indigenous Emergency Interface Record</td><td>Indigenous Health and Protected-Knowledge Interface Record</td><td><code>extends</code></td><td>An emergency action, observation, assistance mission, or data/knowledge process may affect an Indigenous people, nation, territory, resource, relation, or protected knowledge.</td><td>affected Indigenous authority and designated interface function</td><td>AC-4</td><td>ECRC-05; ECRC-10; ECRC-20; ECRC-30</td><td>Closed by affected authority, completion of obligations, or documented non-engagement; survival of non-transfer terms is explicit.</td><td>none</td></tr><tr><td><code>ECRC-12</code> Affected-Community Liaison Record</td><td>direct canonical import</td><td><code>imports</code></td><td>Communities face material effects, displacement, restrictions, uncertainty, or operational presence.</td><td>affected-community liaison function</td><td>AC-2</td><td>ECRC-11 where applicable; ECRC-13; ECRC-21</td><td>Closed after obligations, grievances, and unresolved issues are transferred or resolved.</td><td>none — direct import applies when triggered</td></tr><tr><td><code>ECRC-13</code> Rights and Non-Derogation Record</td><td>Rights and Less-Restrictive-Means Record</td><td><code>extends</code></td><td>A proposed or active measure may affect rights, liberties, equality, accessibility, bodily integrity, livelihood, family life, due process, or protected continuity.</td><td>rights-protection and non-derogation review function</td><td>AC-2</td><td>ECRC-06; ECRC-08; ECRC-14 or ECRC-15 when applicable; ECRC-30</td><td>Updated throughout the measure and closed only after restoration and outstanding remedies are recorded.</td><td>none</td></tr><tr><td><code>ECRC-14</code> Health Measure and Bodily Integrity Record</td><td>Vaccination or Prophylaxis Requirement + Countermeasure Evidence and Authorization</td><td><code>splits</code></td><td>A measure affects vaccination, prophylaxis, testing, treatment, triage, medical examination, sample collection, or other bodily integrity.</td><td>competent health-measure and bodily-integrity authority</td><td>AC-2</td><td>ECRC-13; ECRC-19; ECRC-22; ECRC-30</td><td>Closed after expiry, follow-up, data/sample disposition, and unresolved claims transfer.</td><td>none</td></tr><tr><td><code>ECRC-15</code> Isolation, Evacuation, and Shelter Record</td><td>Isolation or Quarantine Review Record</td><td><code>extends</code></td><td>People may be isolated, quarantined, evacuated, excluded, relocated, or housed in emergency shelter.</td><td>competent isolation, evacuation, or shelter authority</td><td>AC-2</td><td>ECRC-13; ECRC-17; ECRC-18; ECRC-22; ECRC-30</td><td>Closed by release/return, property and service restoration, and disposition of personal data.</td><td>none</td></tr><tr><td><code>ECRC-16</code> Emergency Work Mobilisation Record</td><td>Health Worker and Responder Safety Record</td><td><code>extends</code></td><td>Workers, volunteers, community responders, contractors, public servants, or security personnel are mobilized.</td><td>employer, professional-command, and worker-protection function</td><td>AC-2</td><td>ECRC-09; ECRC-13; ECRC-18; ECRC-30</td><td>Closed after demobilisation, final pay, claims transfer, credential return, and follow-up arrangements.</td><td>none</td></tr><tr><td><code>ECRC-17</code> Essential Services and AUBI Continuity Record</td><td>Essential Care Continuity Record</td><td><code>extends</code></td><td>An emergency may interrupt essential care, utilities, food, shelter, communications, justice, income support, or AUBI Layer 1.</td><td>essential-service and social-protection continuity function</td><td>AC-2</td><td>ECRC-03; ECRC-08; ECRC-18; ECRC-23</td><td>Closed after ordinary capacity is restored or a lawful long-term transition is approved.</td><td>none</td></tr><tr><td><code>ECRC-18</code> Emergency Finance and Compensation Record</td><td>Finance, Procurement, and Stockpile Record</td><td><code>extends</code></td><td>Emergency funds, forecast finance, procurement, guarantees, reserves, compensation, or extraordinary expenditures are used.</td><td>competent fiscal, procurement, and compensation function</td><td>AC-2</td><td>ECRC-06; ECRC-08; ECRC-16; ECRC-17; ECRC-30</td><td>Closed by audited reconciliation, compensation-reserve transfer, and lawful disposition of residual funds.</td><td>none</td></tr><tr><td><code>ECRC-19</code> Data, Privacy, Security, and Secrecy Record</td><td>Health-Data Authority and Access Record</td><td><code>extends</code></td><td>Emergency observation or action processes personal, health, genetic, operational, infrastructure, model, communications, or security-sensitive data.</td><td>authorized data custodian and security function</td><td>AC-2</td><td>ECRC-02; ECRC-11 or ECRC-20 where applicable; ECRC-21; ECRC-29</td><td>Remains active until ECRC-29 verifies disposition or a valid ordinary-law basis replaces the emergency basis.</td><td>none</td></tr><tr><td><code>ECRC-20</code> Protected Knowledge and Non-Transfer Record</td><td>Indigenous Health and Protected-Knowledge Interface Record</td><td><code>extends</code></td><td>Knowledge, samples, genetic material, cultural information, sacred relations, source identities, security information, or dual-use material requires protected handling.</td><td>protected-knowledge authority or lawful custodian</td><td>AC-4</td><td>ECRC-11; ECRC-19; ECRC-24 when evidence is involved</td><td>Closed only when the originating authority confirms disposition or continuing obligations are transferred.</td><td>none</td></tr><tr><td><code>ECRC-21</code> Public Information and Correction Record</td><td>Public Information and Correction Record</td><td><code>implements</code></td><td>Authorities or operational bodies issue warnings, advice, uncertainty statements, corrections, orders, or service information.</td><td>authorized public-information and correction function</td><td>AC-2</td><td>ECRC-03; ECRC-07 or ECRC-08 for legal orders; ECRC-12; ECRC-19</td><td>Closed when superseded, corrected, archived, and linked to final after-action account.</td><td>none</td></tr><tr><td><code>ECRC-22</code> Interim Measure Review Record</td><td>direct canonical import</td><td><code>imports</code></td><td>A provisional, urgent, ex parte, restrictive, or protective measure is taken before full ordinary process.</td><td>urgent protective-review function</td><td>AC-2</td><td>ECRC-06; ECRC-08; ECRC-13; ECRC-24; ECRC-25</td><td>Closed by timely review and implementation of continuation, termination, or restoration.</td><td>none — direct import applies when triggered</td></tr><tr><td><code>ECRC-23</code> Cross-Border Assistance Record</td><td>Host Request and Assistance Acceptance Record</td><td><code>extends</code></td><td>Assistance, personnel, assets, funds, data, samples, or services cross jurisdictional boundaries.</td><td>requesting, host-acceptance, and cross-border assistance functions</td><td>AC-2</td><td>ECRC-05; ECRC-09; ECRC-10; ECRC-18; ECRC-19</td><td>Closed after handback, financial reconciliation, data disposition, claims transfer, and authority restoration.</td><td>none</td></tr><tr><td><code>ECRC-24</code> Investigation and Evidence Handoff Record</td><td>Investigation and Evidence Handoff Record</td><td><code>implements</code></td><td>Potential wrongdoing, liability, causation, regulatory breach, or rights violation requires evidence transfer to a competent investigative or prosecutorial function.</td><td>investigation and evidence-custody function</td><td>AC-5</td><td>ECRC-19; ECRC-20; ECRC-25 only if separately initiated</td><td>Closed by acknowledged custody transfer, rejection/return, or lawful disposition.</td><td>none</td></tr><tr><td><code>ECRC-25</code> Adjudication and Enforcement Handoff Record</td><td>Adjudication and Enforcement Handoff Record</td><td><code>implements</code></td><td>A competent authority seeks adjudication, recognition, remedy, injunction, sanction, or execution by a separately authorized body.</td><td>competent adjudication or enforcement-referral function</td><td>AC-2</td><td>ECRC-05; ECRC-06; ECRC-22 where interim relief exists; ECRC-24 as evidence reference</td><td>Closed by final disposition, execution report, stay, withdrawal, or transfer to ordinary process.</td><td>none</td></tr><tr><td><code>ECRC-26</code> Renewal State Estimate</td><td>Renewal Health State Estimate</td><td><code>extends</code></td><td>A provisional or time-limited emergency action is proposed for continuation, especially beyond 72 hours, 30 days, or 90 cumulative days.</td><td>renewing authority with independent review</td><td>AC-2</td><td>ECRC-03; ECRC-06; ECRC-08; ECRC-13; ECRC-22; ECRC-27</td><td>Closed by renewal decision, expiry, termination, or transition to ordinary law.</td><td>none</td></tr><tr><td><code>ECRC-27</code> Emergency Termination Certificate</td><td>Emergency Termination Certificate</td><td><code>implements</code></td><td>An emergency declaration, power, mission, facility control, restriction, or extraordinary coordination ends.</td><td>terminating authority</td><td>AC-2</td><td>ECRC-08; ECRC-09; ECRC-26; ECRC-28; ECRC-29; ECRC-30</td><td>Closed only when linked restoration and disposition obligations are verified, not merely announced.</td><td>none</td></tr><tr><td><code>ECRC-28</code> Authority Restoration and Asset Return Record</td><td>Authority, Facility, and Asset Return Record</td><td><code>extends</code></td><td>Emergency authority, facilities, assets, access, credentials, command, custody, or territorial control must return.</td><td>authority, asset, credential, and access-restoration function</td><td>AC-2</td><td>ECRC-27; ECRC-29; ECRC-30</td><td>Closed by verified acceptance or formally recorded unresolved dispute.</td><td>none</td></tr><tr><td><code>ECRC-29</code> Emergency Data Disposition Record</td><td>Health Data and Sample Disposition Record</td><td><code>extends</code></td><td>Emergency powers expire or emergency-purpose data, samples, models, logs, or access rights reach their disposition point.</td><td>emergency-data disposition authority and custodian</td><td>AC-2</td><td>ECRC-19; ECRC-20; ECRC-27; ECRC-28</td><td>Closed by verified disposition or valid continuing ordinary-law authority with review date.</td><td>none</td></tr><tr><td><code>ECRC-30</code> Wrongful Action and Compensation Record</td><td>Wrongful Action and Compensation Record</td><td><code>implements</code></td><td>Action may have been unlawful, excessive, mistaken, discriminatory, harmful, or based on a good-faith false alarm that caused compensable loss.</td><td>claims, restoration, and compensation function</td><td>AC-2</td><td>ECRC-13; ECRC-18; ECRC-24 or ECRC-25 where applicable</td><td>Closed after remedy completion or transfer of unresolved claims to competent process.</td><td>none</td></tr><tr><td><code>ECRC-31</code> After-Action and Ordinary-Capacity Review</td><td>After-Action and Ordinary-Capacity Review</td><td><code>implements</code></td><td>A significant alert, activation, compound event, failed escalation, or emergency response concludes or reaches a major review point.</td><td>independent after-action and ordinary-capacity review function</td><td>AC-2</td><td>ECRC-27; ECRC-28; ECRC-29; ECRC-30; ECRC-33</td><td>Closed when recommendations are accepted, rejected with reasons, or transferred to tracked ordinary governance.</td><td>none</td></tr><tr><td><code>ECRC-32</code> Institutional Sunset or Continuation Record</td><td>Institutional Continuation, Transfer, or Dissolution Record</td><td><code>extends</code></td><td>A temporary emergency body, programme, facility, mandate, dataset, fund, or coordination arrangement reaches review or sunset.</td><td>constituting, continuation, transfer, or sunset authority</td><td>AC-2</td><td>ECRC-31; ECRC-28; ECRC-29; ECRC-33</td><td>Closed by verified continuation under valid authority, transfer, or dissolution.</td><td>none</td></tr><tr><td><code>ECRC-33</code> Unresolved Risk and Dissent Register</td><td>direct canonical import</td><td><code>imports</code></td><td>Material uncertainty, jurisdiction gap, unresolved dissent, residual hazard, uncompleted restoration, or non-scaling decision remains open.</td><td>unresolved-risk and dissent-custody function</td><td>AC-2</td><td>Any ECRC record; especially ECRC-03; ECRC-05; ECRC-27; ECRC-28; ECRC-29; ECRC-31; ECRC-32</td><td>Closed only when the specified closure condition is met and verified.</td><td>none — direct import applies when triggered</td></tr></tbody></table> <h2>Appendix conformance rules</h2> <ul><li>A domain record carries the canonical identifier in its header and preserves the common 27-field header defined by <code>ECRC/0.1</code>.</li> <li>A <code>direct canonical import</code> is instantiated from the profile without waiting for a domain-specific form.</li> <li><code>ECRC-24</code> and <code>ECRC-25</code> are separate records even when transmitted in one package or displayed in one interface.</li> <li>A package that reaches termination is not closed until required restoration, data disposition, claims transfer, unresolved-risk custody, and archival steps are complete.</li> <li>Any later interface, profile, clause, or domain-framework version requires a recorded compatibility test before substitution.</li></ul> <hr> <h1>Appendix L. CDEE and Biological Incident Coordination Addendum conformance</h1> <p><strong>Pinned interfaces:</strong> <code>CDEE/0.1</code> and <code>GH-AE-BICA/0.1</code>.<br> <strong>CDEE SHA-256:</strong> <code>68ee2c48383199e4b91b365ea21e35d5a729f0a72854472acf6f8ae103f0c192</code>.<br> <strong>Biological Addendum SHA-256:</strong> <code>9b666eeb52ee3ca8674ce771661c1633b62c4aab7bcc8545389e551632447dc4</code>.<br> <strong>Biological Packet Schema SHA-256:</strong> <code>6965847e77619b6cffde3775fa988dcae027966a8a9d9e34499d107fbf6b21cb</code>.<br> <strong>Compatibility test:</strong> This patch version is tested against an Addendum originally pinned to the immediately preceding framework versions. The only framework changes are version/reference updates and adoption/conformance text. No health, biosafety, genetic, facility, licensing, public-health, emergency-power, rights, evidence, or remedy semantics changed.</p> <h3>Required use</h3> <p>The Addendum applies when a biological incident engages both Global Health and Aethelred functions, including laboratory exposure, containment deviation, field-release concern, manufacturing contamination, unexplained illness linked to biological activity, biological-data compromise, protected sample analysis, dual-use dispute, or contested origin.</p> <h3>Conformance constraints</h3> <ul><li>One immutable CDEE <code>cluster_event_id</code> links the event; local identifiers remain distinct.</li> <li>Origin hypotheses may remain natural, ecological, industrial, laboratory-associated, field-release, deliberate, mixed, unrelated, or unknown.</li> <li>Responsibility is assigned by function; no framework receives whole-event ownership.</li> <li>Handoffs require explicit acknowledgement and acceptance state; silence is not acceptance.</li> <li>Sample, evidence, data, genetic, Indigenous, familial, ecological, and dual-use custody remains purpose-limited and may remain non-transferable.</li> <li><code>ECRC-24</code> evidence transfer remains separate from <code>ECRC-25</code> adjudication or enforcement referral.</li> <li>Each activated authority retains its own 72-hour, 30-day, and 90-day review clocks.</li> <li>Closure requires authority return, facility or health handback, data and sample disposition, claims transfer, correction, and unresolved-causation custody where applicable.</li> <li>Later versions fail closed until the compatibility manifest is updated.</li></ul>",1);function d(e){var i=o();n(940),a(e,i)}export{d as default};
